async function syncLeadStatus(leadId){
 const lead=leadOf(leadId);if(!lead||terminalLeadStage(lead.stage)||completedLeadStage(lead.stage))return lead?.stage;
 const setStage=async stage=>{if(stage!==lead.stage){await writeRecord('leads',{stage,updatedAt:stamp()},leadId)}return stage};
 const activeLoans=(db.loans||[]).filter(loan=>loan.leadId===leadId&&!['Rejected','Closed'].includes(loan.status));
 if(activeLoans.some(loan=>['Sanctioned','Disbursed'].includes(loan.status)))return setStage('LoanProcess Completed');
 if(activeLoans.some(loan=>['Application','Submitted','Under Review','On Hold'].includes(loan.status)))return setStage('LoanProcess InProgress');
 const activeQuotes=(db.quotations||[]).filter(q=>q.leadId===leadId&&!['Rejected','Closed'].includes(q.status));
 if(activeQuotes.some(q=>q.status==='Accepted'))return setStage('Won');
 if(activeQuotes.some(q=>q.status==='Under Negotiation'||q.status==='Revised'||q.status==='Negotiation'))return setStage('Negotiation');
 if(activeQuotes.some(q=>q.status==='Sent'||q.status==='Quote Sent'||q.status==='Quotation Sent'))return setStage('Quotation Sent');
 if(activeQuotes.some(q=>q.status==='Draft'||q.status==='Quotation Draft'))return setStage('Quotation Draft');
 const activeSurveys=(db.surveys||[]).filter(s=>s.leadId===leadId&&!['Closed','Cancelled'].includes(s.status));
 const surveyStatuses=activeSurveys.map(s=>normalizeSurveyStatus(s.status));
 if(surveyStatuses.some(status=>status==='Completed'))return setStage('Site Survey Completed');
 if(surveyStatuses.some(status=>status==='Scheduled'))return setStage('Site Survey Scheduled');
 if(activeSurveys.length)return setStage('Site Survey Scheduled');
 const activeFollowups=(db.followups||[]).filter(f=>f.leadId===leadId&&!['Closed','Cancelled'].includes(f.status));
 const followupStatuses=activeFollowups.map(f=>normalizeFollowupStatus(f.status));
 if(followupStatuses.some(status=>status==='Completed'))return setStage('Followup Completed');
 if(followupStatuses.some(status=>status==='InProgress'))return setStage(lead.stage==='Negotiation'||lead.stage==='Followup Negotiation'?'Followup Negotiation':'Followup Scheduled');
 if(activeFollowups.length)return setStage(lead.stage==='Negotiation'||lead.stage==='Followup Negotiation'?'Followup Negotiation':'Followup Scheduled');
 const childStages=['Followup Scheduled','Followup Completed','Site Survey Scheduled','Site Survey Completed','Quotation Draft','Quotation Sent','Negotiation','Followup Negotiation','LoanProcess InProgress','LoanProcess Completed'];
 if(childStages.includes(lead.stage))return setStage('New');
 return lead.stage;
}
async function closeTerminalLead(lead,reason){if(!terminalLeadStage(lead.stage))return;const now=stamp(),collections=['followups','surveys','quotations'];for(const collection of collections){for(const record of (db[collection]||[]).filter(item=>item.leadId===lead.id)){const closure=collection==='followups'?{status:'Closed',closedAt:now,closedReason:reason}:collection==='surveys'?{status:'Closed',closedAt:now,closedReason:reason}:{status:'Rejected',closedAt:now,closedReason:reason};await writeRecord(collection,closure,record.id)}}for(const payment of (db.payments||[]).filter(item=>item.leadId===lead.id&&item.status==='Promised'))await writeRecord('payments',{status:'Cancelled',closedAt:now,closedReason:reason},payment.id)}
