function parseLeadCsv(text){
 const rows=[];let row=[],field='',quoted=false;
 for(let i=0;i<text.length;i++){const ch=text[i];if(quoted){if(ch==='"'&&text[i+1]==='"'){field+='"';i++}else if(ch==='"')quoted=false;else field+=ch}else if(ch==='"'&&field==='')quoted=true;else if(ch===','){row.push(field);field=''}else if(ch==='\n'||ch==='\r'){if(ch==='\r'&&text[i+1]==='\n')i++;row.push(field);if(row.some(value=>value.trim()!==''))rows.push(row);row=[];field=''}else field+=ch}
 if(quoted)throw Error('The CSV has an unfinished quoted field. Check the file and try again.');
 row.push(field);if(row.some(value=>value.trim()!==''))rows.push(row);
 if(rows.length<2)throw Error('The CSV needs a header row and at least one lead.');
 const normalize=value=>value.toLowerCase().replace(/[^a-z0-9]+/g,' ').trim(),headers=rows[0].map(value=>importHeaderFields[normalize(value)]||importHeaderFields[normalize(value).replace(/ /g,'')]);
 for(const fieldName of ['customerName','phone','capacityKw'])if(!headers.includes(fieldName))throw Error(`Missing required column: ${leadTemplateHeaders[['customerName','phone','capacityKw'].indexOf(fieldName)]}. Download a fresh template and keep its column headers.`);
 return rows.slice(1).map(values=>{const data={customerName:'',phone:'',city:'',category:'Residential',capacityKw:'',monthlyBill:'',source:'Referral',stage:'New',nextFollowUp:'',notes:''};headers.forEach((name,index)=>{if(name)data[name]=(values[index]||'').trim()});return validateLeadImportRow(data)})
}
function importDate(value){
 const raw=String(value||'').trim();if(!raw)return '';
 if(/^\d{4}-\d{2}-\d{2}$/.test(raw)){const date=new Date(`${raw}T00:00:00Z`);return !Number.isNaN(date.valueOf())&&date.toISOString().slice(0,10)===raw?raw:null}
 if(/^\d{1,2}\/\d{1,2}\/\d{4}$/.test(raw)){const [day,month,year]=raw.split('/').map(Number),date=new Date(Date.UTC(year,month-1,day));return date.getUTCFullYear()===year&&date.getUTCMonth()===month-1&&date.getUTCDate()===day?date.toISOString().slice(0,10):null}
 if(/^\d{1,5}(\.\d+)?$/.test(raw)){const date=new Date(Date.UTC(1899,11,30)+Math.floor(Number(raw))*86400000);return date.toISOString().slice(0,10)}
 const parsed=new Date(raw);return Number.isNaN(parsed.valueOf())?null:parsed.toISOString().slice(0,10)
}
function validateLeadImportRow(data){
 const row={...data,customerName:String(data.customerName||'').trim(),phone:String(data.phone||'').trim(),city:String(data.city||'').trim(),notes:String(data.notes||'').trim()};
 const errors=[];
 if(!row.customerName)errors.push('Customer name is required');
 if(!row.phone)errors.push('Mobile number is required');
 const capacity=String(row.capacityKw??'').replace(/,/g,'').trim(),capacityNumber=Number(capacity);if(!capacity||!Number.isFinite(capacityNumber)||capacityNumber<=0)errors.push('Capacity must be greater than 0');else row.capacityKw=capacityNumber;
 const bill=String(row.monthlyBill??'').replace(/,/g,'').trim();if(bill&&(!Number.isFinite(Number(bill))||Number(bill)<0))errors.push('Monthly EB bill must be 0 or greater');else if(bill)row.monthlyBill=Number(bill);else row.monthlyBill='';
 const option=(value,choices,fallback,label)=>{const match=choices.find(choice=>choice.toLowerCase()===String(value||'').trim().toLowerCase());if(match)return match;errors.push(`Choose a valid ${label}`);return fallback};
 row.category=option(row.category,types,'Residential','project category');row.source=option(row.source,SOURCES,'Referral','lead source');row.stage=option(normalizeLeadStage(row.stage),STAGES,'New','sales stage');
 const date=importDate(row.nextFollowUp);if(date===null)errors.push('Next follow-up must be a valid date');else row.nextFollowUp=date;
 return {data:row,errors}
}
