 serviceTicket:{collection:'serviceTickets',label:'Service ticket',lead:true,fields:[{name:'ticketNo',label:'Ticket number'},{name:'ticketType',label:'Issue type',type:'select',options:['Inverter fault','Panel output','Wiring','Net meter','Monitoring','Other'],default:'Inverter fault'},{name:'priority',label:'Priority',type:'select',options:['Normal','High','Urgent'],default:'Normal'},{name:'openedOn',label:'Opened on',type:'date',default:today()},{name:'dueDate',label:'Target resolution',type:'date'},{name:'status',label:'Ticket status',type:'select',options:TICKET_STATUSES,default:'Open'},{name:'notes',label:'Issue and resolution notes',type:'textarea'}]}
