function openFeatureRecord(kind,existing){
 const config=FEATURE_FORMS[kind];if(!config)return;
 const requiredFeature=kind==='amc'||kind==='serviceTicket'?'afterSales':kind==='survey'?'surveys':kind==='inventory'?'inventory':kind==='subsidy'?'subsidies':'loans';if(!planHasFeature(requiredFeature)){toast(`${workspacePlan().name} does not include ${PAGES[requiredFeature]?.[0]||'this feature'}.`,true);return}
 if(config.lead&&!visible(db.leads).length){toast('Create a lead first.',true);goPage('leads');return}
 if(kind==='inventory'&&!canManageInventory()){toast('Only workspace managers can change shared inventory.',true);return}
 const record=existing||{},fields=`${config.lead?(existing?`<div class="full"><strong>${esc(leadOf(record.leadId)?.customerName||'')}</strong></div>`:formLead()):''}${config.fields.map(field=>featureFieldMarkup(field,record)).join('')}`;
 openModal(existing?`Update ${config.label}`:`Add ${config.label}`,config.lead?'Record details linked to the customer project':'Shared product, rate and stock details',fields,async values=>{
  const data={...values};
  for(const field of config.fields)if(field.type==='number'||['gstRate'].includes(field.name))data[field.name]=num(data[field.name]);
  if(kind==='survey')data.photoLinks=String(data.photoLinks||'').split(/\r?\n/).map(x=>x.trim()).filter(Boolean);
  if(config.lead){const leadId=existing?.leadId||values.leadId,lead=leadOf(leadId);if(!lead)throw Error('Select a valid customer lead.');if(terminalLeadStage(lead.stage))throw Error('Terminal Lost or Junk leads cannot have new child activity.');data.leadId=leadId;data.assignedTo=lead.assignedTo}
  else{data.assignedTo=existing?.assignedTo||uid();if(kind==='inventory')data.shared=true}
  if(kind==='loan'){
   data.trancheAmount=num(data.trancheAmount||0);
   if(data.status==='Disbursed'&&(!data.sanctionedOn||num(data.trancheAmount)<=0))throw Error('A disbursed bank tranche requires a sanction date and approved tranche amount.');
   if(data.advanceExceptionApproved==='Yes'&&!businessManager())throw Error('Only the Business Owner can approve a bank advance-release exception.');
   if(data.status==='Disbursed')data.advanceReleaseEvidence=data.trancheTrigger||'';data.advanceApprovedBy=data.advanceExceptionApproved==='Yes'?uid():existing?.advanceApprovedBy||'';data.advanceApprovedAt=data.advanceExceptionApproved==='Yes'?stamp():existing?.advanceApprovedAt||'';
  }
  if(data.quantity<0||data.amount<0||data.unitRate<0)throw Error('Amounts and quantities must not be negative.');
  data.updatedAt=stamp();if(!existing){data.createdAt=stamp();data.createdBy=uid()}
  const savedId=await writeRecord(config.collection,data,existing?.id);if(kind==='inventory')await syncCatalogFromInventory({...data,id:savedId});
  if(kind==='survey')await syncLeadStatus(data.leadId);
 },existing&&HISTORY_TYPES[config.collection]?{recordType:HISTORY_TYPES[config.collection],recordId:existing.id}:null)
}
function openCatalogItem(existing){if(!businessManager()){toast('Only the Business Manager can manage the shared product catalog.',true);return}const item=existing||{};openModal(existing?'Update catalog product':'Add catalog product','Shared quotation products are available on every plan. Inventory and stock remain Scale-only.',`${input('name','Product name',item.name||'','text',true)}${input('category','Category',item.category||'Solar Panel','text',true)}${input('brand','Brand',item.brand||'','text')}${input('unit','Unit',item.unit||'piece','text',true)}${input('unitRate','Unit rate before GST (₹)',item.unitRate??'','number',true,'min="0" step="0.01"')}${select('gstRate','GST rate (%)',[String(DEFAULT_GST_RATE)],String(DEFAULT_GST_RATE))}`,async values=>{const data={...values,unitRate:num(values.unitRate),gstRate:num(values.gstRate),tenantId:tenantId(),updatedAt:stamp()};if(!existing){data.createdAt=stamp();data.createdBy=uid()}await writeRecord('catalog',data,existing?.id)})}
function openStockMovement(product){
 if(!planHasFeature('stockMovements')){toast(`${workspacePlan().name} does not include stock movements.`,true);return}
 if(!canManageInventory()){toast('Only workspace managers can change shared inventory.',true);return}
 const projects=[{id:'',name:'No linked project'},...visible(db.installations).map(item=>({id:item.leadId,name:`${leadOf(item.leadId)?.customerName||'Project'} · ${item.id}`}))];
 openModal('Record stock movement',`${product.name} · current stock ${num(product.quantity)} ${product.unit||'units'}`,`${select('direction','Movement',['receive','issue'].map(x=>({id:x,name:x==='receive'?'Stock received':'Issue to project'})),'receive')}${input('quantity','Quantity',1,'number',true,'min="0.01" step="0.01"')}${select('leadId','Project (required when issuing)',projects,'',false)}${input('movementDate','Movement date',today(),'date',true)}${textarea('notes','Supplier / issue notes','')}`,async values=>{
  const quantity=num(values.quantity);if(quantity<=0)throw Error('Enter a quantity greater than zero.');
  if(values.direction==='issue'&&!values.leadId)throw Error('Choose a project when issuing material.');
  const project=values.leadId?leadOf(values.leadId):null;if(values.leadId&&!project)throw Error('Select a valid project.');
  const delta=values.direction==='issue'?-quantity:quantity,newQuantity=num(product.quantity)+delta;
  if(newQuantity<0)throw Error('There is not enough stock to issue that quantity.');
  const movement={productId:product.id,productName:product.name,direction:values.direction,quantity,unit:product.unit||'units',leadId:project?.id||'',tenantId:tenantId(),assignedTo:uid(),movementDate:values.movementDate,notes:values.notes,createdAt:stamp(),createdBy:uid()};
  if(isDemo){product.quantity=newQuantity;product.updatedAt=stamp();movement.id='SM-'+Date.now().toString(36)+Math.floor(Math.random()*999);db.stockMovements.unshift(movement);saveDemo()}
  else{
   const productRef=fb.api.doc(fb.store,'inventory',product.id),movementRef=fb.api.doc(fb.api.collection(fb.store,'stockMovements'));
   await fb.api.runTransaction(fb.store,async transaction=>{const snapshot=await transaction.get(productRef);if(!snapshot.exists())throw Error('Product no longer exists. Refresh and retry.');const current=num(snapshot.data().quantity);if(values.direction==='issue'&&current<quantity)throw Error('There is not enough stock to issue that quantity. Refresh and retry.');transaction.update(productRef,{quantity:current+delta,updatedAt:stamp()});transaction.set(movementRef,movement)})
  }
 })
}
function renderTeam(team){if(!canManageTeam(team))return empty('You do not have permission to view this team.');const roles=superAdmin()?(team==='sales'?['business_owner','sales_manager','sales_executive']:['project_manager','project_executive']):teamRoles(team),users=db.users.filter(user=>user.active!==undefined&&roles.includes(user.role)),memberLabel=superAdmin()?'Company users':team==='sales'?'Sales Team':'Project Team',activityLabel=team==='sales'?'Assigned leads':'Assigned projects';return `<div class="panel"><div class="table-top"><div><div class="panel-title">${memberLabel} <span class="muted-small">(${users.length} accounts)</span></div><div class="panel-subtitle">${superAdmin()?'Manage every provisioned user in the selected company.':'Provision login accounts in Firebase Authentication first.'}</div></div></div>${table(['Employee','Login email','Role',activityLabel,'Status','Action'],users.map(user=>`<tr><td>${userChip(user.id)}</td><td>${esc(user.email||'—')}</td><td>${esc(roleLabel(user.role))}</td><td>${team==='sales'?db.leads.filter(lead=>lead.assignedTo===user.id).length:db.installations.filter(project=>project.assignedTo===user.id).length}</td><td>${user.active?tag('Active'):tag('Inactive')}</td><td>${businessManager()||canManageTeam(team)&&user.role===memberRole(team)?`<button class="cell-action" data-act="edit-team" data-id="${esc(user.id)}">Manage →</button>`:'View only'}</td></tr>`).join(''))}<div class="panel-head"><div class="info-note" style="width:100%">${superAdmin()?'Changes affect only the selected company.':'To add a member, create or invite their Firebase Authentication account first, then enter the matching UID. Deactivating a profile removes CRM access without deleting its Firebase login.'}</div></div></div>`}
function renderProfile(){const authUser=fb.auth?.currentUser,providers=authUser?.providerData?.map(p=>p.providerId)||[];const signInMethod=isDemo?'Demo account':providers.includes('google.com')?'Google':providers.includes('password')?'Email and password':'Firebase Authentication';const email=currentUser.email||authUser?.email||'—';const rows=[['Name',currentUser.name||'Team member'],['Email',email],['Company',companyName()],['Role',roleLabel(currentUser.role)],['Sign-in method',signInMethod],['Account ID',isDemo?'Demo account':uid()]];return `<div class="panel settings-card"><h3>${esc(currentUser.name||'My profile')}</h3><p>Account details for your ${esc(companyName())} workspace.</p><div class="divider"></div>${table(['Profile detail','Value'],rows.map(([label,value])=>`<tr><td><strong>${esc(label)}</strong></td><td>${esc(value)}</td></tr>`).join(''))}</div>`}
function renderSubscription(){return `<div class="panel settings-card"><h3>${esc(companyName())} — ${isDemo?'demo preview':'live company portal'}</h3><p>${isDemo?'You are exploring the PRO workflow preview with sample data. Changes are saved only in this browser.':'Your team signs in through Firebase Authentication and shares data via Cloud Firestore.'}</p><div class="divider"></div><h3>Company subscription</h3><p>Current plan: <strong>${esc(workspacePlan().name)}</strong> · ${num(db.workspace?.activeUserCount)} of ${planSeatLimit()} active users.</p><div class="info-note">Subscription details are read-only. Contact a Super Admin to change your plan or account status.</div></div>`}
function renderGlobalSubscriptions(){const planOptions=Object.entries(PLAN_LIMITS).map(([id,plan])=>({id,name:`${plan.name} · ${plan.seats} users`}));const demoNotice=isDemo?'<div class="info-note">Preview only: these fictional companies and changes are stored in this browser. No Firebase account or live subscription is involved.</div>':'';const onboarding=isDemo?'<div class="subscription-create"><h3>Company onboarding</h3><p>Live onboarding is disabled in this local preview. It requires a pre-created Firebase Authentication account.</p></div>':`<div class="subscription-create"><h3>Onboard a company</h3><p>Create the owner's Firebase Authentication account first. Enter that account's exact UID below; the new workspace starts with empty CRM data.</p><div class="form-grid">${input('newCompanyName','Company name','','text',true)}${input('newOwnerName','Admin name','','text',true)}${input('newOwnerEmail','Admin email','','email',true)}${input('newOwnerUid','Pre-created Firebase Auth UID','','text',true)}${select('newCompanyPlan','Subscription tier',planOptions,'starter')}</div><button class="btn primary" type="button" data-create-company>Create workspace</button></div>`;return `<div class="panel subscription-admin"><h2>Company subscriptions</h2><p>Manage all companies and select a workspace to access its CRM records, team, reports, and settings.</p>${demoNotice}${onboarding}<div class="subscription-list"><h3>All companies (${db.workspaces.length})</h3>${table(['Company','Plan','Active users','Status','Subscription management'],db.workspaces.map(workspace=>`<tr><td><strong>${esc(workspace.name||'Unnamed company')}</strong><br><span class="muted-small">${esc(workspace.id)}</span></td><td><select aria-label="Plan for ${esc(workspace.name)}" data-company-plan="${esc(workspace.id)}">${planOptions.map(plan=>`<option value="${esc(plan.id)}" ${workspace.plan===plan.id?'selected':''}>${esc(plan.name.split(' · ')[0])}</option>`).join('')}</select></td><td>${num(workspace.activeUserCount)}</td><td>${tag(workspace.active?'Active':'Suspended')}</td><td><button class="btn subtle" type="button" data-update-company-plan="${esc(workspace.id)}">Save plan</button> <button class="btn ${workspace.active?'danger':'subtle'}" type="button" data-toggle-company-status="${esc(workspace.id)}">${workspace.active?'Suspend':'Reactivate'}</button></td></tr>`).join(''))}</div></div>`}
async function createCompanyWorkspace(){if(!superAdmin()||isDemo)return;const value=name=>String($(`#page-content [name="${name}"]`)?.value||'').trim(),name=value('newCompanyName'),ownerName=value('newOwnerName'),email=value('newOwnerEmail'),ownerUid=value('newOwnerUid'),plan=value('newCompanyPlan');if(!name||!ownerName||!email||!ownerUid||!PLAN_LIMITS[plan]){toast('Enter the company name, owner details, Firebase Auth UID, and a valid plan.',true);return}if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)){toast('Enter a valid business owner email address.',true);return}if(ownerUid.length>128||ownerUid.includes('/')){toast('Enter the exact Firebase Auth UID (up to 128 characters).',true);return}try{const workspaceId=crypto.randomUUID(),updatedAt=stamp(),workspaceRef=fb.api.doc(fb.store,'workspaces',workspaceId),directoryRef=fb.api.doc(fb.store,'tenantDirectory',workspaceId),ownerRef=fb.api.doc(fb.store,'users',ownerUid),metadata={name,plan,active:true,activeUserCount:1,updatedAt},batch=fb.api.writeBatch(fb.store);batch.set(workspaceRef,metadata);batch.set(directoryRef,metadata);batch.set(ownerRef,{name:ownerName,email,role:'business_owner',active:true,tenantId:workspaceId});await batch.commit();await fetchWorkspaces();render();$('#workspace-plan-label').textContent=`${db.workspaces.length} companies`;toast(`${name} workspace created with empty CRM data.`)}catch(error){loginError(error)}}
async function updateCompanyPlan(workspaceId){if(!superAdmin())return;const plan=$(`#page-content [data-company-plan="${CSS.escape(workspaceId)}"]`)?.value;if(!PLAN_LIMITS[plan]){toast('Select a valid subscription tier.',true);return}if(isDemo){const workspace=db.workspaces.find(item=>item.id===workspaceId);if(!workspace)return;workspace.plan=plan;if(db.workspace?.id===workspaceId)db.workspace.plan=plan;saveDemo();render();showApp();toast(`Demo only: ${workspace.name} plan changed to ${PLAN_LIMITS[plan].name}.`);return}try{const updatedAt=stamp(),batch=fb.api.writeBatch(fb.store);batch.update(fb.api.doc(fb.store,'workspaces',workspaceId),{plan,updatedAt});batch.update(fb.api.doc(fb.store,'tenantDirectory',workspaceId),{plan,updatedAt});await batch.commit();await fetchWorkspaces();if(db.workspace?.id===workspaceId)await fetchRecords();render();showApp();toast('Company subscription updated.')}catch(error){loginError(error)}}
async function toggleCompanyStatus(workspaceId){if(!superAdmin())return;const workspace=db.workspaces.find(item=>item.id===workspaceId);if(!workspace)return;if(isDemo){workspace.active=!workspace.active;if(db.workspace?.id===workspaceId)db.workspace.active=workspace.active;saveDemo();render();showApp();toast(`Demo only: ${workspace.name} is now ${workspace.active?'active':'suspended'}.`);return}try{const active=!workspace.active,updatedAt=stamp(),batch=fb.api.writeBatch(fb.store);batch.update(fb.api.doc(fb.store,'workspaces',workspaceId),{active,updatedAt});batch.update(fb.api.doc(fb.store,'tenantDirectory',workspaceId),{active,updatedAt});await batch.commit();await fetchWorkspaces();if(db.workspace?.id===workspaceId)await fetchRecords();render();showApp();toast(`${workspace.name} workspace ${active?'suspended':'reactivated'}.`)}catch(error){loginError(error)}}
async function saveWorkspacePlan(){if(!superAdmin()){toast('Only a Super Admin can change the subscription tier.',true);return}const plan=$('#page-content [name="workspacePlan"]')?.value;if(!PLAN_LIMITS[plan]){toast('Select a valid subscription tier.',true);return}try{if(isDemo){db.workspace.plan=plan;saveDemo()}else await fb.api.updateDoc(fb.api.doc(fb.store,'workspaces',tenantId()),{plan,updatedAt:stamp()});await refresh();$('#workspace-plan-label').textContent=`${workspacePlan().name} · ${num(db.workspace?.activeUserCount)}/${planSeatLimit()} users`;toast(`Workspace plan set to ${PLAN_LIMITS[plan].name}`)}catch(error){loginError(error)}}
function bindFilters(){let t=$('#filter-search'),f=$('#filter-status');if(t)t.addEventListener('input',e=>{searchText=e.target.value; const cursor=e.target.selectionStart;render();let n=$('#filter-search');if(n){n.focus();n.setSelectionRange(cursor,cursor)}});if(f)f.addEventListener('change',e=>{selectedFilter=e.target.value;render()})}
function globalSearchMatches(query){
 const term=query.trim().toLowerCase();if(!term)return [];
 const sources=[
  {type:'lead',label:'Lead',page:'leads',collection:'leads',rows:visible(db.leads),title:r=>r.customerName,detail:r=>`${r.phone||'No phone'} · ${r.city||'No city'} · ${r.stage}`,text:r=>[r.id,r.customerName,r.phone,r.city,r.category,r.stage,r.source,r.notes,r.capacityKw].join(' ')},
  {type:'followup',label:'Follow-up',page:'followups',collection:'followups',rows:visible(db.followups),title:r=>leadOf(r.leadId)?.customerName||'Follow-up',detail:r=>`${r.type} · ${dateLabel(r.dueDate)} · ${r.status}`,text:r=>[r.id,leadOf(r.leadId)?.customerName,r.type,r.dueDate,r.status,r.notes].join(' ')},
  {type:'quotation',label:'Quotation',page:'quotations',collection:'quotations',rows:visible(db.quotations),title:r=>leadOf(r.leadId)?.customerName||r.id,detail:r=>`${r.systemType} · ${r.status} · ${money(r.price)}`,text:r=>[r.id,leadOf(r.leadId)?.customerName,r.systemType,r.status,r.notes,r.price,r.capacityKw].join(' ')},
  {type:'installation',label:'Installation',page:'installations',collection:'installations',rows:visible(db.installations),title:r=>leadOf(r.leadId)?.customerName||'Installation',detail:r=>`${r.status} · ${r.installer||'No installer'} · ${dateLabel(r.targetDate)}`,text:r=>[r.id,leadOf(r.leadId)?.customerName,leadOf(r.leadId)?.city,r.status,r.installer,r.notes,r.targetDate,r.capacityKw].join(' ')},
  {type:'collection',label:'Collection',page:'payments',collection:'payments',rows:visible(db.payments),title:r=>leadOf(r.leadId)?.customerName||'Collection',detail:r=>`${r.kind} · ${r.status} · ${money(r.amount)}`,text:r=>[r.id,leadOf(r.leadId)?.customerName,r.kind,r.status,r.amount,r.dueDate].join(' ')}
  ,{type:'survey',label:'Site survey',page:'surveys',collection:'surveys',rows:visible(db.surveys),title:r=>leadOf(r.leadId)?.customerName||'Site survey',detail:r=>`${r.status} · ${dateLabel(r.surveyDate)}`,text:r=>[r.id,leadOf(r.leadId)?.customerName,r.discom,r.status,r.notes].join(' ')}
  ,{type:'subsidy',label:'Subsidy',page:'subsidies',collection:'subsidies',rows:visible(db.subsidies),title:r=>leadOf(r.leadId)?.customerName||'Subsidy application',detail:r=>`${r.status} · ${r.applicationNo||'No application number'}`,text:r=>[r.id,leadOf(r.leadId)?.customerName,r.applicationNo,r.status,r.notes].join(' ')}
  ,{type:'loan',label:'Loan',page:'loans',collection:'loans',rows:visible(db.loans),title:r=>leadOf(r.leadId)?.customerName||'Solar loan',detail:r=>`${r.bank||'Lender'} · ${r.status}`,text:r=>[r.id,leadOf(r.leadId)?.customerName,r.bank,r.applicationNo,r.status].join(' ')}
  ,{type:'serviceTicket',label:'Service ticket',page:'afterSales',collection:'serviceTickets',rows:visible(db.serviceTickets),title:r=>leadOf(r.leadId)?.customerName||'Service ticket',detail:r=>`${r.ticketType} · ${r.status}`,text:r=>[r.id,r.ticketNo,leadOf(r.leadId)?.customerName,r.ticketType,r.status,r.notes].join(' ')}
 ];
 return sources.flatMap(source=>source.rows.flatMap(record=>{
  const title=source.title(record),searchable=source.text(record).toLowerCase();if(!searchable.includes(term))return [];
  return [{type:source.type,label:source.label,page:source.page,collection:source.collection,id:record.id,title,detail:source.detail(record),score:title.toLowerCase().startsWith(term)?0:1}]
 })).sort((a,b)=>a.score-b.score||a.title.localeCompare(b.title)).slice(0,10)
}
function renderGlobalSearch(){
 const input=$('#global-search-input'),results=$('#global-search-results'),matches=globalSearchMatches(input.value);
 if(!input.value.trim()){results.innerHTML='';results.classList.add('hidden');input.setAttribute('aria-expanded','false');return}
 results.innerHTML=matches.length?matches.map(result=>`<button type="button" class="global-search-result" role="option" data-global-search-type="${result.type}" data-global-search-id="${esc(result.id)}"><span class="global-search-kind">${result.label}</span><span class="global-search-result-copy"><strong>${esc(result.title)}</strong><small>${esc(result.detail)}</small></span><span class="global-search-arrow" aria-hidden="true">→</span></button>`).join(''):'<div class="global-search-empty" role="status">No matching records</div>';
 results.classList.remove('hidden');input.setAttribute('aria-expanded','true')
}
function closeGlobalSearch(){const input=$('#global-search-input'),results=$('#global-search-results');if(!input||!results)return;results.classList.add('hidden');input.setAttribute('aria-expanded','false')}
function openGlobalSearchResult(type,id){
 const targets={lead:{collection:'leads',page:'leads',open:openLead},followup:{collection:'followups',page:'followups',open:openFollowup},quotation:{collection:'quotations',page:'quotations',open:openQuote},installation:{collection:'installations',page:'installations',open:openInstallation},collection:{collection:'payments',page:'payments',open:openPayment},survey:{collection:'surveys',page:'surveys',open:openFeatureRecord,kind:'survey'},subsidy:{collection:'subsidies',page:'subsidies',open:openFeatureRecord,kind:'subsidy'},loan:{collection:'loans',page:'loans',open:openFeatureRecord,kind:'loan'},serviceTicket:{collection:'serviceTickets',page:'afterSales',open:openFeatureRecord,kind:'serviceTicket'}},target=targets[type],record=target&&db[target.collection].find(item=>item.id===id);
 if(!target||!record){toast('Record not found',true);return}
 closeGlobalSearch();$('#global-search-input').value='';goPage(target.page);target.kind?target.open(target.kind,record):target.open(record)
}
function goPage(p){if(!PAGES[p])return;if(!featurePageAllowed(p)){toast(p==='subscription'?`${PAGES[p][0]} is available only to a Super Admin.`:`${workspacePlan().name} does not include ${PAGES[p][0]}.`,true);return}closeGlobalSearch();currentPage=p;searchText='';selectedFilter='';$('#sidebar').classList.remove('open');$('#mobile-overlay').classList.add('hidden');render();window.scrollTo({top:0,behavior:'smooth'})}
function input(name,label,val='',type='text',required=false,extra=''){return `<label>${label}<input name="${name}" type="${type}" value="${esc(val)}" ${required?'required':''} ${extra}></label>`}
function select(name,label,options,current,required=true){return `<label>${label}<select name="${name}" ${required?'required':''}>${options.map(x=>{let val=typeof x==='string'?x:x.id;let txt=typeof x==='string'?x:x.name;return `<option value="${esc(val)}" ${String(val)===String(current)?'selected':''}>${esc(txt)}</option>`}).join('')}</select></label>`}
function textarea(name,label,val=''){return `<label class="full">${label}<textarea name="${name}">${esc(val)}</textarea></label>`}
function choiceLeads(onlyWon=false){return visible(db.leads).filter(l=>!onlyWon||l.stage==='Won').map(l=>({id:l.id,name:l.customerName+' · '+fmtKw(l.capacityKw)}))}
function assignees(current){return select('assignedTo','Assigned salesperson',db.users.filter(u=>u.active&&['sales_executive','sales_manager'].includes(u.role)).map(u=>({id:u.id,name:u.name})),current||defaultRecordAssignee())}
function historyPanelMarkup(recordType,recordId){const entries=db.history.filter(x=>x.recordType===recordType&&x.recordId===recordId).sort((a,b)=>(b.createdAt||'').localeCompare(a.createdAt||''));return `<section class="record-history"><div class="record-history-heading"><h3>History</h3><span>Read-only timeline</span></div><div class="history-list">${entries.length?entries.map(x=>`<article class="history-entry"><div class="history-entry-top"><strong>${esc(x.event||'Comment added')}</strong><time>${esc(x.createdAt?new Date(x.createdAt).toLocaleString('en-IN',{dateStyle:'medium',timeStyle:'short'}):'')}</time></div><div class="history-author">${esc(x.actorName||'Team member')}</div>${Object.prototype.hasOwnProperty.call(x,'newValue')?`<div class="history-change"><div><span>Previous · ${esc(x.fieldLabel||'Value')}</span><p>${esc(x.previousValue||'(empty)')}</p></div><div><span>Updated · ${esc(x.fieldLabel||'Value')}</span><p>${esc(x.newValue||'(empty)')}</p></div></div>`:''}${x.comment?`<p>${esc(x.comment)}</p>`:''}</article>`).join(''):'<div class="empty">No history yet.</div>'}</div><div class="record-history-compose"><label for="record-history-comment">Add a comment</label><textarea id="record-history-comment" maxlength="2000" placeholder="Record a conversation or update..."></textarea><button type="button" class="btn subtle" data-add-history>Add comment</button></div></section>`}
function bindRecordHistory(root,recordMeta){const button=root.querySelector('[data-add-history]');if(!button)return;button.addEventListener('click',async()=>{const textarea=root.querySelector('#record-history-comment'),comment=textarea.value.trim();if(!comment)return;button.disabled=true;try{await createHistory({...recordMeta,event:'Comment added',comment});if(!isDemo)await fetchRecords();root.querySelector('.record-history').outerHTML=historyPanelMarkup(recordMeta.recordType,recordMeta.recordId);bindRecordHistory(root,recordMeta);toast('Comment added to history')}catch(err){loginError(err)}finally{const nextButton=root.querySelector('[data-add-history]');if(nextButton)nextButton.disabled=false}})}
function openModal(title,subtitle,fields,onSave,recordMeta){
 const root=$('#modal-root');
 root.innerHTML=`<div class="modal-layer"><div class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-header"><div><h2>${esc(title)}</h2><p>${esc(subtitle)}</p></div><button class="icon-btn" id="close-modal" aria-label="Close">✕</button></div><form id="modal-form" style="display:contents"><div class="modal-body"><div class="form-grid">${fields}</div>${recordMeta?historyPanelMarkup(recordMeta.recordType,recordMeta.recordId):''}</div><div class="modal-foot"><button type="button" class="btn subtle" id="cancel-modal">Cancel</button><button id="save-modal" type="submit" class="btn primary">Save record →</button></div></form></div></div>`;
 root.querySelector('.modal-layer').addEventListener('click',e=>{if(e.target.classList.contains('modal-layer'))closeModal()});
 $('#close-modal').onclick=closeModal;$('#cancel-modal').onclick=closeModal;
 $('#modal-form').addEventListener('submit',async e=>{
  e.preventDefault();if(busy)return;busy=true;$('#save-modal').disabled=true;
  try{const data=Object.fromEntries(new FormData(e.target).entries());await onSave(data);closeModal();await refresh();toast('Saved successfully')}
  catch(err){loginError(err)}
  finally{busy=false;const button=$('#save-modal');if(button)button.disabled=false}
 });
 const productSelect=root.querySelector('[name="productId"]');
 if(productSelect)productSelect.addEventListener('change',()=>{
  const product=db.catalog.find(item=>item.id===productSelect.value);if(!product)return;
  root.querySelector('[name="unitPrice"]').value=product.unitRate;
  root.querySelector('[name="gstRate"]').value=String(DEFAULT_GST_RATE)
 });
 const lineItemsField=root.querySelector('[name="lineItems"]');
 if(lineItemsField){
  const lines=JSON.parse(lineItemsField.value||'[]'),list=root.querySelector('[data-quote-lines]');
  const renderLines=()=>{
   lineItemsField.value=JSON.stringify(lines);
   list.innerHTML=lines.length?`<div class="quote-line-list">${lines.map((item,index)=>`<div class="quote-line-row"><strong>${esc(item.productName)}</strong><span>${num(item.quantity)} × ${money(item.unitPrice)}</span><span>GST ${num(item.gstRate)}%</span><strong>${money(num(item.quantity)*num(item.unitPrice)*(1+num(item.gstRate)/100))}</strong><button class="cell-action" type="button" data-remove-quote-line="${index}" aria-label="Remove ${esc(item.productName)}">Remove</button></div>`).join('')}</div>`:'<p class="info-note">Add one or more catalog products to calculate the project quote.</p>'
  };
  const productPick=root.querySelector('[name="quoteProductPick"]');
  productPick.addEventListener('change',()=>{
   const product=db.catalog.find(item=>item.id===productPick.value);if(!product)return;
   root.querySelector('[name="quoteUnitPrice"]').value=product.unitRate;
   root.querySelector('[name="quoteGstRate"]').value=String(DEFAULT_GST_RATE)
  });
  root.querySelector('[data-quote-add]').addEventListener('click',()=>{
   const product=db.catalog.find(item=>item.id===productPick.value),quantity=num(root.querySelector('[name="quoteQuantity"]').value),unitPrice=num(root.querySelector('[name="quoteUnitPrice"]').value);
   if(quantity<=0||unitPrice<=0){toast('Enter a positive quantity and unit rate before adding a quotation item.',true);return}
   lines.push({productId:product?.id||'',productName:product?.name||'Solar project item',quantity,unitPrice,gstRate:num(root.querySelector('[name="quoteGstRate"]').value)});
   renderLines()
  });
  list.addEventListener('click',event=>{
   const remove=event.target.closest('[data-remove-quote-line]');if(!remove)return;
   lines.splice(Number(remove.dataset.removeQuoteLine),1);renderLines()
  });
  renderLines()
 }
 const leadSelect=root.querySelector('[name="leadId"]'),capacityInput=root.querySelector('[name="capacityKw"]'),centralInput=root.querySelector('[name="centralSubsidy"]');
 if(leadSelect&&capacityInput){
  const updateLeadDefaults=resetCapacity=>{
   const lead=leadOf(leadSelect.value);if(!lead)return;
   if(resetCapacity||!capacityInput.value)capacityInput.value=lead.capacityKw;
   if(centralInput&&centralInput.dataset.manual!=='true')centralInput.value=centralSubsidyEstimate(capacityInput.value,lead.category)
  };
  leadSelect.addEventListener('change',()=>updateLeadDefaults(true));
  updateLeadDefaults(false);
  capacityInput.addEventListener('input',()=>{
   const lead=leadOf(leadSelect.value);
   if(centralInput&&centralInput.dataset.manual!=='true'&&lead)centralInput.value=centralSubsidyEstimate(capacityInput.value,lead.category)
  });
  if(centralInput)centralInput.addEventListener('input',()=>{centralInput.dataset.manual='true'})
 }
 if(recordMeta)bindRecordHistory(root,recordMeta)
}
